// === Tab: mySketch.js ===
let palette = ['#000000', '#5debfd'];
let vmin, vmax;
let glsl;

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1332189/files/shader.vert', 'shader.frag');
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  vmin = (width < height) ? width : height;
  vmax = (width > height) ? width : height;
  perspective(80 / 180 * PI, width / height, 0.1, vmax * 5);
  smooth();
  noStroke();

  let d = vmin * 0.65;
  camera(d, -d, d);
}

function draw() {
  background(palette[0]);

  orbitControl();

  shader(glsl);
  glsl.setUniform('uTime', millis() / 1000);
  glsl.setUniform('uDepth', vmax);
  glsl.setUniform('uColor0', color(palette[0])._array);
  glsl.setUniform('uColor1', color(palette[1])._array);

  push();
  { 
    push();
    {
      rotateX(PI / 2);
      plane(vmax * 3);
    }
    pop();

    let N = 8;
    let step = vmin / N;
    for (let i = 0; i < N; i++) {
      let x = (i - N / 2) * step;
      for (let j = 0; j < N; j++) {
        let z = (j - N / 2) * step;
        let n = noise(i, j);
        let h = map(n, 0, 1, 0.5, 4) * step;
        let sz = step * 0.5;
        push();
        {
          translate(-x, -h / 2, -z);
          box(sz, h, sz);
        }
        pop();
      }
    }
  }
  pop();
}

// === Tab: shader.frag ===
precision mediump float;

uniform float uTime;
uniform float uDepth;
uniform vec4 uColor0;
uniform vec4 uColor1;

varying vec2 vTexCoord;
varying vec4 vPos;

void main() {
  vec2 uv = vTexCoord;
  float d = vPos.z / uDepth;
  float l = 0.015 / (1.0 - fract(d * 1.0 - uTime * 0.1 - 0.15));
  vec3 color = mix(uColor0.rgb, uColor1.rgb, l);

  gl_FragColor = vec4(color, 1.0);
}

// === Tab: shader.vert ===
attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec3 aNormal;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

varying vec2 vTexCoord;
varying vec4 vPos;

void main() {
  vTexCoord = aTexCoord;
  vec4 position = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * position;
  vPos = gl_Position;
}

